tool_calls:
mkdir -p /home/eval/pkgs/bin /home/eval/pkgs/build
cat > /home/eval/pkgs/bin/order <<'EOF'
#!/usr/bin/bash
# Sort the vertices once, then always choose the first ready vertex.
set -o pipefail
export LC_ALL=C
if [[ $# -ne 1 ]]; then
    printf 'usage: %s dependency-file\n' "$0" >&2
    exit 2
fi
awk '
function trim(s) {
    sub(/^[ \t\r\n]+/, "", s)
    sub(/[ \t\r\n]+$/, "", s)
    return s
}
{
    sub(/#.*/, "")
    line = trim($0)
    if (line == "") next
    colon = index(line, ":")
    package = trim(substr(line, 1, colon - 1))
    print "V\t" package
    rest = trim(substr(line, colon + 1))
    if (rest == "") next
    count = split(rest, deps, /[ \t]+/)
    for (i = 1; i <= count; i++) {
        print "V\t" deps[i]
        print "E\t" deps[i] "\t" package
    }
}
' < "$1" | sort -u | awk -F '\t' '
$1 == "E" {
    edge[$2 SUBSEP $3] = 1
    needed[$3]++
}
$1 == "V" { names[++n] = $2 }
END {
    for (step = 1; step <= n; step++) {
        chosen = 0
        for (i = 1; i <= n; i++) {
            if (!done[names[i]] && needed[names[i]] == 0) {
                chosen = i
                break
            }
        }
        if (!chosen) {
            message = "cycle: "
            separator = ""
            for (i = 1; i <= n; i++) {
                if (!done[names[i]]) {
                    message = message separator names[i]
                    separator = " "
                }
            }
            print message > "/dev/stderr"
            exit 1
        }
        package = names[chosen]
        print package
        done[package] = 1
        for (i = 1; i <= n; i++) {
            if ((package SUBSEP names[i]) in edge) needed[names[i]]--
        }
    }
}
'
EOF
chmod +x /home/eval/pkgs/bin/order
cd /home/eval/pkgs
bin/order deps.txt > build/order.txt
bin/order deps-big.txt > build/big-order.txt
bin/order deps-cycle.txt > build/cycle-order.txt 2> build/cycle.txt
rc=$?
printf '%s\n' "$rc" > build/cycle.rc
cat build/order.txt
cat build/cycle-order.txt
cat build/cycle.txt
cat build/cycle.rc

